<?php
/** @var array{css:?string,js:?string} $assets */
/** @var array<int, array<string, string>> $navigation */
/** @var array<string, mixed>|null $vehicle */
/** @var array<string, mixed> $data */
/** @var array<string, string> $errors */
/** @var array<string, array<int, array<string, mixed>>> $options */
/** @var array<string, mixed>|null $onboarding */
$editing = $vehicle !== null;
$value = static fn (string $field, mixed $default = ''): mixed => $data[$field] ?? $default;
$select = static function (string $field, array $items) use ($value): string {
    $html = '<option value="">Choose</option>';
    foreach ($items as $item) {
        $selected = (int) $value($field) === (int) $item['id'] ? ' selected' : '';
        $html .= '<option value="' . (int) $item['id'] . '"' . $selected . '>' . esc($item['name']) . '</option>';
    }
    return $html;
};
?>
