<?php if ($onboarding !== null): ?><section class="section tone-info"><div class="section-heading"><p class="eyebrow">Discovered from Turo</p><h2><?= esc((string) $onboarding['vehicle_name']) ?></h2></div><dl class="issue-facts"><div><dt>Turo vehicle ID</dt><dd><?= esc((string) $onboarding['turo_vehicle_id']) ?></dd></div><div><dt>Year</dt><dd><?= esc((string) ($onboarding['year'] ?? 'Not provided')) ?></dd></div><div><dt>Make / model</dt><dd><?= esc(trim((string) ($onboarding['make'] ?? '') . ' ' . (string) ($onboarding['model'] ?? ''))) ?: 'Not provided' ?></dd></div><div><dt>Affected rows</dt><dd><?= (int) $onboarding['affected_issue_count'] ?></dd></div></dl><p class="muted">Complete the FleetOS-required information below. The mapping will be created from the authoritative unresolved import issue.</p></section><?php endif; ?>
<?php if ($errors !== []): ?><section class="section import-message tone-danger"><strong>Correct the vehicle information.</strong><ul><?php foreach ($errors as $error): ?><li><?= esc($error) ?></li><?php endforeach; ?></ul></section><?php endif; ?>
